import{_ as t,o as s,c as o,j as e}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"为文件存储目录添加权限","description":"","frontmatter":{"title":"为文件存储目录添加权限","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","常见需求","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第十部分：常见需求/文件上传/为文件存储目录添加权限.md","filePath":"posts/java快速入门/第十部分：常见需求/文件上传/为文件存储目录添加权限.md"}'),n={name:"posts/java快速入门/第十部分：常见需求/文件上传/为文件存储目录添加权限.md"};function r(l,a,p,d,m,_){return s(),o("div",null,[...a[0]||(a[0]=[e("div",null,[e("p",null,'在 macOS 中，/home 目录是自动装载点（automount point），并且被系统保留为 NFS（网络文件系统）使用。当你尝试在这个目录下创建文件或目录时，会收到 "Operation not supported" 的错误。'),e("p",null,"对于大多数 macOS 用户来说，用户的家目录是在 /Users/ 下，而不是 /home/。虽然 /home/ 在文件系统树中存在，但是它的用途与 Linux 中的 /home/ 并不相同。这就是为什么在尝试在 /home/ 下创建目录时，你会收到错误。"),e("p",null,"因此，你应该在 /Users/ 下创建你的目录。你可以运行以下命令："),e("p",null,"bash Copy code mkdir -p /Users/$(whoami)/hzz/dcdb/2023/07 这将在你的用户目录下创建所需的目录。$(whoami) 是一个会被你的用户名替换的 shell 变量。然后在你的应用程序中，你需要使用新的路径，即：/Users/你的用户名/hzz/dcdb/2023/07。"),e("p",null,"如果你确实需要在 /home/ 下创建目录（例如，如果你有特殊的需求或设置），你可能需要更改系统设置或使用其他高级技术，这通常需要更深入的系统知识，并可能需要采取措施避免破坏系统。在大多数情况下，我建议你使用 /Users/你的用户名/ 路径，而不是尝试在 /home/ 下创建目录。")],-1)])])}const h=t(n,[["render",r]]);export{c as __pageData,h as default};
